const raw = $input.item.json.output;
let plan;

if (typeof raw === 'object' && raw !== null && !Array.isArray(raw)) {
  plan = raw;
} else {
  const text = String(raw || '');
  if (!text.trim()) {
    throw new Error('Analyzer Agent returned empty output');
  }

  let cleaned = text
    .replace(/```json\s*/gi, '')
    .replace(/```\s*/gi, '')
    .trim();

  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end === -1) {
    throw new Error('No JSON object found in output\nRaw: ' + text.substring(0, 500));
  }

  const jsonStr = cleaned.substring(start, end + 1);
  try {
    plan = JSON.parse(jsonStr);
  } catch(e) {
    // Fix trailing commas (common Llama quirk)
    try {
      plan = JSON.parse(jsonStr.replace(/,\s*([}\]])/g, '$1'));
    } catch(e2) {
      throw new Error('Invalid JSON: ' + e2.message + '\nRaw: ' + text.substring(0, 500));
    }
  }
}

// â”€â”€ Normalize common Llama key aliases â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const keyAliases = {
  'target_framework_updates': [
    'framework_updates', 'targetFrameworkUpdates', 'target_frameworks',
    'framework_changes', 'frameworks', 'targetframeworkupdates'
  ],
  'package_updates': [
    'packageUpdates', 'nuget_updates', 'packages', 'package_changes',
    'nuget_packages', 'dependencies', 'packageupdates'
  ],
  'file_changes': [
    'fileChanges', 'code_changes', 'files', 'source_changes',
    'code_updates', 'filechanges', 'changes'
  ],
  'startup_changes': [
    'startupChanges', 'startup_updates', 'program_changes',
    'hosting_changes', 'startupchanges'
  ],
  'nuget_versions_needed': [
    'nugetVersionsNeeded', 'versions_needed', 'nuget_versions',
    'version_lookups', 'packages_to_resolve', 'nugetversionsneeded'
  ],
  'risk_level': [
    'riskLevel', 'risk', 'risklevel'
  ],
  'risk_notes': [
    'riskNotes', 'notes', 'risk_description', 'risknotes', 'risk_assessment'
  ],
  'estimated_changes': [
    'estimatedChanges', 'change_count', 'total_changes',
    'num_changes', 'estimatedchanges', 'estimated_count'
  ]
};

// Build lowercase key map for case-insensitive matching
const planKeysLower = {};
for (const k of Object.keys(plan)) {
  planKeysLower[k.toLowerCase().replace(/[_\s]/g, '')] = k;
}

for (const [canonical, aliases] of Object.entries(keyAliases)) {
  if (canonical in plan) continue; // already correct
  // Try exact aliases first
  for (const alias of aliases) {
    if (alias in plan) {
      plan[canonical] = plan[alias];
      delete plan[alias];
      break;
    }
  }
  // Try lowercase normalized match
  if (!(canonical in plan)) {
    const normalizedCanonical = canonical.toLowerCase().replace(/_/g, '');
    const matchedKey = planKeysLower[normalizedCanonical];
    if (matchedKey && matchedKey !== canonical) {
      plan[canonical] = plan[matchedKey];
      delete plan[matchedKey];
    }
  }
}

// â”€â”€ Validate required keys (with diagnostic showing what keys ARE present) â”€â”€
const required = ['target_framework_updates', 'package_updates', 'file_changes', 'risk_level', 'estimated_changes', 'source_framework'];
const missingKeys = required.filter(k => !(k in plan));
if (missingKeys.length > 0) {
  throw new Error(
    'Migration plan missing keys: ' + missingKeys.join(', ') +
    '\nKeys received: ' + Object.keys(plan).join(', ')
  );
}

// â”€â”€ Coerce to arrays defensively â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
for (const k of ['target_framework_updates', 'package_updates', 'file_changes', 'startup_changes', 'nuget_versions_needed']) {
  if (!plan[k]) plan[k] = [];
  if (!Array.isArray(plan[k])) plan[k] = [plan[k]];
}


// ── Force target_framework_updates to must ──
for (const item of (plan.target_framework_updates || [])) {
  item.priority = 'must';
}

// ── Default missing priority to must ──
for (const key of ['package_updates', 'startup_changes', 'nuget_versions_needed']) {
  for (const item of (plan[key] || [])) {
    if (!item.priority || !['must', 'should'].includes(item.priority)) {
      item.priority = 'must';
    }
  }
}
for (const fc of (plan.file_changes || [])) {
  for (const change of (fc.changes || [])) {
    if (!change.priority || !['must', 'should'].includes(change.priority)) {
      change.priority = 'must';
    }
  }
}

// ── Dependency propagation (packages referenced by must file changes) ──
const mustPackages = new Set();
for (const fc of (plan.file_changes || [])) {
  for (const change of (fc.changes || [])) {
    if (change.priority === 'must') {
      const usingMatches = (change.new || '').match(/using\s+([\w.]+)/g) || [];
      for (const u of usingMatches) {
        const ns = u.replace('using ', '').replace(';', '').trim().split('.')[0];
        mustPackages.add(ns);
      }
    }
  }
}

for (const pkg of (plan.package_updates || [])) {
  if (pkg.priority === 'should' && mustPackages.has(pkg.name.split('.')[0])) {
    pkg.priority = 'must';
  }
}
for (const pkg of (plan.nuget_versions_needed || [])) {
  if (pkg.priority === 'should' && mustPackages.has(pkg.package.split('.')[0])) {
    pkg.priority = 'must';
  }
}

// Ensure risk_level is valid
if (!['low', 'medium', 'high'].includes(plan.risk_level)) {
  plan.risk_level = 'medium'; // safe default
}

if (plan.risk_level === 'high') {
  plan._warning = 'HIGH RISK â€” review risk_notes before proceeding';
}


// ── Deterministic guards (moved out of the prompt) ──────────────────
const FRAMEWORK_REFS = ['microsoft.netcore.app', 'microsoft.aspnetcore.app', 'microsoft.windowsdesktop.app'];
const stripped = [];

plan.package_updates = (plan.package_updates || []).filter(p => {
  if (FRAMEWORK_REFS.includes(String(p.name || '').toLowerCase())) { stripped.push(p.name); return false; }
  return true;
});
plan.nuget_versions_needed = (plan.nuget_versions_needed || []).filter(p => {
  if (FRAMEWORK_REFS.includes(String(p.package || '').toLowerCase())) { stripped.push(p.package); return false; }
  return true;
});

// Merge duplicate file_changes entries for the same file (overlapping replacements break execution)
const byFile = {};
for (const fc of (plan.file_changes || [])) {
  const key = fc.file;
  if (!byFile[key]) byFile[key] = { file: key, changes: [] };
  byFile[key].changes.push(...(fc.changes || []));
}
plan.file_changes = Object.values(byFile);

// Reject empty targetContent up front
for (const fc of plan.file_changes) {
  fc.changes = (fc.changes || []).filter(c => c.old && String(c.old).trim().length > 0);
}
plan.file_changes = plan.file_changes.filter(fc => fc.changes.length > 0);

if (stripped.length) {
  plan.risk_notes = (plan.risk_notes || '') +
    ' [validator] Removed implicit framework references from the package list: ' + stripped.join(', ') + '.';
}

// Recompute estimated_changes from what actually survived
plan.estimated_changes =
  (plan.target_framework_updates || []).length +
  (plan.package_updates || []).length +
  (plan.file_changes || []).reduce((n, fc) => n + (fc.changes || []).length, 0) +
  (plan.startup_changes || []).length;

return [{ json: {
  migration_plan: JSON.stringify(plan),
  plan_validated: true,
  risk_level: plan.risk_level
}}];

// Hoisted: `this` is the node context only at top level, not inside the nested
// resolvePackage() function declaration below.
const helpers = this.helpers;

const planStr = $input.item.json.migration_plan;
const plan = JSON.parse(planStr);
const tfm = String(($('Webhook').first().json.body.target_framework) || 'net8.0').toLowerCase();

const LADDER = {
  'net10.0': ['net10.0','net9.0','net8.0','net7.0','net6.0','net5.0','netcoreapp3.1','netstandard2.1','netstandard2.0'],
  'net9.0':  ['net9.0','net8.0','net7.0','net6.0','net5.0','netcoreapp3.1','netstandard2.1','netstandard2.0'],
  'net8.0':  ['net8.0','net7.0','net6.0','net5.0','netcoreapp3.1','netstandard2.1','netstandard2.0'],
  'net7.0':  ['net7.0','net6.0','net5.0','netcoreapp3.1','netstandard2.1','netstandard2.0'],
  'net6.0':  ['net6.0','net5.0','netcoreapp3.1','netstandard2.1','netstandard2.0']
};
const allowed = LADDER[tfm] || LADDER['net8.0'];

function normTfm(s) {
  if (!s) return 'any';
  let t = String(s).toLowerCase().trim();
  if (t.startsWith('.netcoreapp,version=v')) t = 'net' + t.split('v')[1];
  else if (t.startsWith('.netstandard,version=v')) t = 'netstandard' + t.split('v')[1];
  else if (t.startsWith('.netframework,version=v')) t = 'netframework' + t.split('v')[1];
  return t.split('-')[0];
}
function cmpDesc(a, b) {
  const pa = String(a.version).split('.').map(Number);
  const pb = String(b.version).split('.').map(Number);
  for (let i = 0; i < 4; i++) { if ((pa[i]||0) !== (pb[i]||0)) return (pb[i]||0) - (pa[i]||0); }
  return 0;
}

// Packages explicitly being removed must never be resolved or re-pinned.
const removedPackages = new Set(
  (plan.package_updates || [])
    .filter(p => p.action === 'remove')
    .map(p => String(p.name || '').toLowerCase())
);

// Drop contradictory entries: the formatter sometimes lists a removed package
// in nuget_versions_needed as well. Removal wins.
const droppedContradictions = [];
plan.nuget_versions_needed = (plan.nuget_versions_needed || []).filter(pkg => {
  if (removedPackages.has(String(pkg.package || '').toLowerCase())) {
    droppedContradictions.push(pkg.package);
    return false;
  }
  return true;
});

// The version each package is pinned at TODAY. This - not the upgrade target -
// is what carries the repo's current advisory and deprecation risk.
const currentVersions = new Map();
for (const pkg of (plan.package_updates || [])) {
  const name = String(pkg.name || '').toLowerCase();
  const from = String(pkg.from_version || '').trim();
  if (name && from) currentVersions.set(name, from);
}

// Packages marked "remove" are audited but never resolved or re-pinned: the
// vulnerable version is still present in the repo until the migration runs.
const packagesToCheck = [];
const seenNames = new Set();
for (const pkg of (plan.package_updates || [])) {
  if (!pkg.name || seenNames.has(pkg.name)) continue;
  seenNames.add(pkg.name);
  packagesToCheck.push({ name: pkg.name, auditOnly: pkg.action === 'remove' });
}
for (const pkg of (plan.nuget_versions_needed || [])) {
  if (!pkg.package || seenNames.has(pkg.package)) continue;
  seenNames.add(pkg.package);
  packagesToCheck.push({ name: pkg.package, auditOnly: false });
}

// Resolve one package: registration index -> pages (parallel) -> newest compatible stable version.

// ── v6.8 third-party package handling ───────────────────────────────────────
// Resolution policy. The v5.x resolver took the NEWEST TFM-compatible version,
// which on the fixture meant RestSharp 106.11.7 -> 114.0.0 (8 majors, a full API
// rewrite) when 106.12.0 is already net9-compatible, and AutoMapper 10.1.1 (MIT)
// -> 16.2.0 (commercial) when 14.0.0 is MIT and targets net8.0.
// Nothing in this pipeline can verify third-party API changes - no tool covers
// them - so the smallest compatible jump is the one whose unverifiable surface
// is smallest. Flip to false to restore v6.7 behaviour.
const PREFER_LOWEST_COMPATIBLE = true;
// Flag a jump this many majors or more as unverified.
const MAJOR_SPAN_WARN = 3;

function verParts(v) { return String(v || '0').split('-')[0].split('.').map(Number); }
function cmpAsc(a, b) {
  const pa = verParts(a), pb = verParts(b);
  for (let i = 0; i < 4; i++) { if ((pa[i] || 0) !== (pb[i] || 0)) return (pa[i] || 0) - (pb[i] || 0); }
  return 0;
}
function verGte(a, b) { return cmpAsc(a, b) >= 0; }
function majorOf(v) { return verParts(v)[0] || 0; }
function licOf(e) { return String((e && e.licenseExpression) || '').trim(); }
function isClean(e) { return !(e.vulnerabilities || []).length && !e.deprecation; }

async function resolvePackage(target) {
  const pkgName = target.name;
  const auditOnly = !!target.auditOnly;
  const out = { pkgName, auditOnly, version: null, warnings: [], vulnerabilities: [], severities: [], deprecated: false };
  try {
    const reg = await helpers.httpRequest({
      method: 'GET',
      url: `https://api.nuget.org/v3/registration5-gz-semver2/${String(pkgName).toLowerCase()}/index.json`,
      json: true
    });

    const pages = await Promise.all((reg.items || []).map(async (page) => {
      if (page.items) return page.items;
      try {
        const p = await helpers.httpRequest({ method: 'GET', url: page['@id'], json: true });
        return p.items || [];
      } catch (e) { return []; }
    }));

    let entries = [];
    for (const items of pages) {
      for (const it of items) if (it.catalogEntry) entries.push(it.catalogEntry);
    }

    const allEntries = entries.slice();
    entries = entries.filter(e => e.listed !== false && !String(e.version).includes('-'));
    entries.sort(cmpDesc);

    // ── Current-version audit: the advisories that actually apply right now ──
    const fromVersion = currentVersions.get(String(pkgName).toLowerCase());
    let fromEntry = null;
    if (fromVersion) {
      const current = allEntries.find(e => String(e.version) === fromVersion);
      fromEntry = current || null;
      if (current) {
        for (const v of (current.vulnerabilities || [])) {
          out.vulnerabilities.push(`${pkgName} ${fromVersion} (in use): severity=${v.severity} ${v.advisoryUrl}`);
          out.severities.push(Number(v.severity));
          out.inUseSeverity = Math.max(Number.isFinite(out.inUseSeverity) ? out.inUseSeverity : -1, Number(v.severity));
        }
        if (current.deprecation) {
          out.deprecated = true;
          out.warnings.push(`${pkgName} ${fromVersion} (in use) is deprecated: ${current.deprecation.message || 'see nuget.org'}`);
        }
      } else {
        out.warnings.push(`${pkgName}: pinned version ${fromVersion} not found on nuget.org; current advisories could not be checked`);
      }
    }

    // A package being removed is not resolved or re-pinned - the audit above is
    // the whole point of looking it up.
    if (auditOnly) return out;

    if (!entries.length) {
      out.version = 'lookup-failed';
      out.warnings.push(`${pkgName}: no listed stable version`);
      return out;
    }

    const isCompatible = (e) => {
      const groups = (e.dependencyGroups || []).map(g => normTfm(g.targetFramework));
      if (!groups.length || groups.includes('any')) return true;
      return groups.some(g => allowed.includes(g));
    };
    // 'entries' is sorted newest-first; compatible[0] stays the newest compatible.
    const compatible = entries.filter(isCompatible);
    const newestCompatible = compatible.length ? compatible[0] : null;

    let chosen = newestCompatible;
    if (PREFER_LOWEST_COMPATIBLE && compatible.length) {
      // Never downgrade below what the repo already pins.
      const forward = fromVersion
        ? compatible.filter(e => verGte(e.version, fromVersion))
        : compatible.slice();
      const pool0 = forward.length ? forward : compatible.slice();
      // Prefer versions with no advisory and no deprecation...
      const clean = pool0.filter(isClean);
      let pool = clean.length ? clean : pool0;
      // ...and among those, ones that keep the licence the repo is already on.
      const fromLic = fromEntry ? licOf(fromEntry) : '';
      if (fromLic) {
        const sameLic = pool.filter(e => licOf(e) === fromLic);
        if (sameLic.length) pool = sameLic;
      }
      // Lowest acceptable MAJOR, then the HIGHEST version inside it. Preferring
      // the lowest version outright was wrong: within one major, semver says
      // patches are compatible, so taking 13.0.2 over 13.0.4 forgoes fixes and
      // buys no reduction in API churn. The major is where the churn lives.
      pool.sort((a, b) => cmpAsc(a.version, b.version));
      const lowestMajor = majorOf(pool[0].version);
      const inMajor = pool.filter(e => majorOf(e.version) === lowestMajor);
      inMajor.sort((a, b) => cmpAsc(b.version, a.version));
      chosen = inMajor[0];
    }

    if (!chosen) {
      out.version = 'incompatible';
      out.warnings.push(`${pkgName}: no stable version declares a dependency group compatible with ${tfm} (newest is ${entries[0].version}) - needs human review`);
      return out;
    }

    out.version = chosen.version;

    if (newestCompatible && chosen.version !== newestCompatible.version) {
      out.warnings.push(`${pkgName}: pinned to ${chosen.version} - the lowest ${tfm}-compatible version with no advisory, which minimises unverifiable API change. Newest compatible is ${newestCompatible.version}; upgrade further only if you want its features.`);
    } else if (chosen.version !== entries[0].version) {
      out.warnings.push(`${pkgName}: pinned to ${chosen.version} for ${tfm}; newest overall ${entries[0].version} is not compatible`);
    }

    // Licence change. The registration hive already carries this and v6.7 threw
    // it away: AutoMapper went commercial at v15, so 10.1.1 (MIT) -> 16.2.0 moved
    // the customer off MIT with no warning anywhere in the plan.
    const fromLicence = fromEntry ? licOf(fromEntry) : '';
    const toLicence = licOf(chosen);
    if (fromLicence && toLicence !== fromLicence) {
      out.warnings.push(
        `${pkgName}: LICENCE CHANGE ${fromVersion} was "${fromLicence}" but ${chosen.version} is ${toLicence ? '"' + toLicence + '"' : 'not a standard SPDX licence (see ' + (chosen.licenseUrl || 'nuget.org') + ')'} - needs human review before shipping.`
      );
      out.licenceChanged = true;
    }

    // Major-version span. No tool in this pipeline can verify third-party API
    // changes, so say so rather than implying the code changes were researched.
    if (fromVersion) {
      const span = majorOf(chosen.version) - majorOf(fromVersion);
      if (span >= MAJOR_SPAN_WARN) {
        out.warnings.push(
          `${pkgName}: ${fromVersion} -> ${chosen.version} crosses ${span} major versions. Third-party API changes are NOT verified by this pipeline (no tool covers them); any code change for this package is model recall - review it against the package's own upgrade guide.`
        );
      }
    }
    // Secondary signal: the version we are upgrading TO is itself affected.
    // Skipped when it is the same version already reported as "in use".
    const alreadyReported = currentVersions.get(String(pkgName).toLowerCase()) === String(chosen.version);
    if (!alreadyReported) {
      if (chosen.deprecation) {
        out.warnings.push(`${pkgName} ${chosen.version} (upgrade target) is deprecated: ${chosen.deprecation.message || 'see nuget.org'}`);
        out.deprecated = true;
      }
      for (const v of (chosen.vulnerabilities || [])) {
        out.vulnerabilities.push(`${pkgName} ${chosen.version} (upgrade target - still affected): severity=${v.severity} ${v.advisoryUrl}`);
        out.severities.push(Number(v.severity));
      }
    }
  } catch (e) {
    out.version = 'lookup-failed';
    out.warnings.push(`${pkgName}: lookup failed (${e.message})`);
  }
  return out;
}

// All packages resolved concurrently (was sequential - the main cost of this node).
const results = await Promise.all(packagesToCheck.slice(0, 20).map(resolvePackage));

const resolved = {};
const warnings = [];
const vulnerabilities = [];
const severities = [];
let anyDeprecated = false;
let anyLicenceChange = false;
for (const r of results) {
  if (r.licenceChanged) anyLicenceChange = true;
  if (!r.auditOnly) resolved[r.pkgName] = r.version;
  warnings.push(...r.warnings);
  vulnerabilities.push(...r.vulnerabilities);
  severities.push(...(r.severities || []));
  if (r.deprecated) anyDeprecated = true;
}

plan.package_updates = (plan.package_updates || []).filter(pkg => {
  const v = resolved[pkg.name];
  if (pkg.action === 'remove') return true;
  if (v === 'incompatible' || v === 'lookup-failed') return false;
  if (v) { pkg.resolved_version = v; pkg.to_version = v; }
  return true;
});
plan.nuget_versions_needed = (plan.nuget_versions_needed || []).filter(pkg => {
  const v = resolved[pkg.package];
  if (v === 'incompatible' || v === 'lookup-failed') return false;
  if (v) pkg.version = v;
  return true;
});

if (droppedContradictions.length) {
  warnings.push('[validator] Removed from nuget_versions_needed because package_updates marks them for removal: '
    + droppedContradictions.join(', '));
}

// ── Security floor on priority (v7.0) ─────────────────────────────────────────
// "must" means will not compile or throws; "should" means deprecated but works.
// That rule has no place for a vulnerability: job 101 marked AutoMapper "should"
// (10.1.1 works on net9.0), and as execution applies "must" items only, the run
// would have kept 10.1.1 - a high-severity advisory - behind a clean build. A
// package whose version IN USE has a High or Critical advisory is "must"; the
// warning says why, and the reviewer can still demote it knowingly.
const SEVERITY_LABEL = ['low', 'moderate', 'high', 'critical'];
const inUseSeverity = new Map();
for (const r of results) {
  if (Number.isFinite(r.inUseSeverity) && r.inUseSeverity >= 2) inUseSeverity.set(String(r.pkgName).toLowerCase(), r.inUseSeverity);
}
const promoted = new Map();
for (const [list, field] of [[plan.package_updates, 'name'], [plan.nuget_versions_needed, 'package']]) {
  for (const pkg of (list || [])) {
    const sev = inUseSeverity.get(String(pkg[field] || '').toLowerCase());
    if (sev === undefined || pkg.priority !== 'should') continue;
    pkg.priority = 'must';
    promoted.set(String(pkg[field]).toLowerCase(), { name: pkg[field], sev });
  }
}
for (const p of promoted.values()) {
  warnings.push(`${p.name}: promoted from "should" to "must" - the version in use has a ${SEVERITY_LABEL[p.sev] || 'high'}-severity advisory, ` +
    'and execution applies "must" items only. Demote it only to keep the vulnerable version deliberately.');
}
plan.nuget_security_promoted = [...promoted.values()].map((p) => p.name);

plan.nuget_resolved = resolved;
plan.nuget_warnings = warnings;
plan.nuget_vulnerabilities = vulnerabilities;
// NOTE: nuget warnings are deliberately NOT appended to risk_notes. They are
// surfaced from plan.nuget_warnings on the plan review screen; duplicating them
// here made the reviewer read the same text twice.

// Deterministic risk floor from advisory severity (0=Low 1=Moderate 2=High
// 3=Critical). Only ever raises the level - an analyzer that already decided
// 'high' for non-package reasons is never downgraded.
const RANK = { low: 0, medium: 1, high: 2 };
const maxSeverity = severities.length ? Math.max(...severities.filter(s => Number.isFinite(s))) : -1;
function raiseTo(level) {
  const currentRank = RANK[plan.risk_level];
  if (RANK[level] > (Number.isFinite(currentRank) ? currentRank : 0)) plan.risk_level = level;
}
if (maxSeverity >= 2) {
  raiseTo('high');
} else if (vulnerabilities.length || anyDeprecated) {
  raiseTo('medium');
}
plan.nuget_max_severity = maxSeverity;

return [{ json: {
  migration_plan: JSON.stringify(plan),
  plan_validated: $input.item.json.plan_validated,
  risk_level: plan.risk_level,
  nuget_resolved: resolved,
  nuget_warnings: warnings,
  nuget_vulnerabilities: vulnerabilities,
  session_id: $('Set Context').item.json.session_id
}}];

