let jobId = 'unknown';
try { jobId = $json.job_id; } catch(e) {}
if (!jobId || jobId === 'unknown') { try { jobId = $('Webhook').first()?.json?.body?.job_id; } catch(e) {} }

let detailsStr = '';
try {
  let stdout = $('Clone Repository').first()?.json?.stdout || '';
  let stderr = $('Clone Repository').first()?.json?.stderr || '';
  detailsStr = stdout + '\n' + stderr;
} catch(e) {}

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:5153/api/migrationjob/' + jobId + '/logs',
    body: {
      level: 'info',
      phase: 'Analyze',
      message: "Target repository successfully cloned and verified.",
      details: detailsStr.trim()
    },
    json: true
  });
} catch (e) {}
return $input.all();

let jobId = 'unknown';
try { jobId = $json.job_id; } catch(e) {}
if (!jobId || jobId === 'unknown') { try { jobId = $('Webhook').first()?.json?.body?.job_id; } catch(e) {} }

let detailsStr = '';
try {
  let stdout = $('Run Roslyn Upgrade Assistant').first()?.json?.stdout || '';
  let stderr = $('Run Roslyn Upgrade Assistant').first()?.json?.stderr || '';
  detailsStr = stdout + '\n' + stderr;
} catch(e) {}

// Slice the distilled Upgrade Assistant findings out of stdout so the Research
// Agent can be handed them as verified fact instead of having to spot them inside
// a 10KB dump. Split on the section that FOLLOWS them rather than on /^=== /,
// because the distiller's own output opens with a "=== ... ===" banner.
let uaFindings = '';
try {
  const after = ($('Run Roslyn Upgrade Assistant').first()?.json?.stdout || '')
    .split('=== UPGRADE ASSISTANT FINDINGS ===')[1] || '';
  uaFindings = after.split('=== CSPROJ FILES ===')[0].trim();
  if (/NO_UPGRADE_ASSISTANT_REPORT/.test(uaFindings)) uaFindings = '';
} catch (e) {}

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:5153/api/migrationjob/' + jobId + '/logs',
    body: {
      level: 'info',
      phase: 'Analyze',
      message: "Initial structural analysis completed (build and Upgrade Assistant).",
      details: detailsStr.trim()
    },
    json: true
  });
} catch (e) {}
return $input.all().map(i => ({ json: Object.assign({}, i.json, { ua_findings: uaFindings }) }));

let jobId = 'unknown';
try { jobId = $json.job_id; } catch(e) {}
if (!jobId || jobId === 'unknown') { try { jobId = $('Webhook').first()?.json?.body?.job_id; } catch(e) {} }

let detailsStr = '';
try {
  detailsStr = JSON.stringify($('Analyzer Agent').first()?.json || {}, null, 2);
} catch(e) {}

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:5153/api/migrationjob/' + jobId + '/logs',
    body: {
      level: 'info',
      phase: 'Analyze',
      message: "AI Architecture Analysis completed and plan compiled.",
      details: detailsStr.trim()
    },
    json: true
  });
} catch (e) {}
return $input.all();

let jobId = 'unknown';
try { jobId = $('Execute Webhook').first()?.json?.body?.job_id; } catch(e) {}
if (!jobId || jobId === 'unknown') { try { jobId = $('Webhook').first()?.json?.body?.job_id; } catch(e) {} }

let iterations = 0;
try {
  let loops = $('Error Fixer Loop').all();
  iterations = loops ? loops.length : 0;
} catch(e) {}

let now = Date.now();
let workflowStart = now;
try { workflowStart = $('Init Telemetry').first().json.workflow_start; } catch(e) {}
let executionTimeMs = now - workflowStart;

let nodeExecutions = [];
let llmUsages = [];

function estimateTokens(textStr) {
    if (!textStr) return 0;
    return Math.ceil(textStr.length / 3.0);
}
// USD per 1K tokens (blended in/out estimate, OpenRouter list prices Sept 2026)
const MODEL_COSTS = {
  'deepseek/deepseek-v4.1-flash': 0.00034,
  'deepseek/deepseek-v4-flash-0731:floor': 0.00012,
  'z-ai/glm-5.3-flash': 0.00016,
  'meta-llama/llama-3.3-70b-instruct': 0.0003,
  'openai/gpt-5-mini': 0.0006,
  'z-ai/glm-5.3-flash:floor': 0.00016
};
function getCost(modelName) { return MODEL_COSTS[modelName] || 0.0002; }

function extractTokenUsage(agentNodeName, promptText, agentOutputJson) {
    let fallbackPromptTokens = estimateTokens(promptText);
    let outputText = typeof agentOutputJson === 'string' ? agentOutputJson : JSON.stringify(agentOutputJson);
    let fallbackCompletionTokens = estimateTokens(outputText);

    // Try to get tokenUsage from the Agent node directly natively
    try {
        let usage = $(agentNodeName).last().json.tokenUsage;
        if (usage && usage.promptTokens) {
            return {
                measured: true,
                promptTokens: usage.promptTokens,
                completionTokens: usage.completionTokens || usage.completion_tokens || fallbackCompletionTokens,
                totalTokens: usage.totalTokens || usage.total_tokens || (usage.promptTokens + fallbackCompletionTokens)
            };
        }
    } catch(e) {}

    return { 
        promptTokens: fallbackPromptTokens, 
        completionTokens: fallbackCompletionTokens, 
        totalTokens: fallbackPromptTokens + fallbackCompletionTokens 
    };
}

try {
    let agentStart = $('Pre-Analyzer Agent Telemetry').first().json.agent_start;

    // Pre-Analyzer Agent Telemetry runs BEFORE the Research Agent, so (now - agentStart)
    // is research + formatter, not the formatter. Split it on research_end.
    let researchEnd = null;
    try { researchEnd = $('Log Research Brief').first().json.research_end || null; } catch(e) {}

    if (researchEnd) {
        nodeExecutions.push({
            NodeName: 'Research Agent',
            Phase: 'Phase 1',
            ExecutionTimeMs: researchEnd - agentStart
        });
    }
    nodeExecutions.push({
        NodeName: 'Analyzer Agent',
        Phase: 'Phase 1',
        ExecutionTimeMs: (researchEnd ? now - researchEnd : now - agentStart)
    });

    // The Research Agent dominates Part 1 (job 97: 12m53s, 342k tokens in the n8n
    // UI) and was never recorded at all. n8n does not surface its ReAct token usage
    // to a Code node, so this is an ESTIMATE and is labelled as one in Provider -
    // it cannot see the scratchpad re-send, which is most of the real cost.
    try {
        let researchModel = "deepseek/deepseek-v4.1-flash";
        try {
            const rm = $evaluateExpression('{{ $node["Research LLM"].parameter.model }}');
            if (rm) researchModel = rm;
        } catch(e) {}

        let researchPrompt = '';
        try { researchPrompt = ($('Run Roslyn Upgrade Assistant').first().json.stdout || ''); } catch(e) {}
        let researchBrief = '';
        try { researchBrief = ($('Log Research Brief').first().json.research_brief || ''); } catch(e) {}

        let rUsage = { promptTokens: 0, completionTokens: 0, totalTokens: 0 };
        let measured = false;
        try {
            const u = $('Research Agent').last().json.tokenUsage;
            if (u && u.promptTokens) {
                rUsage = {
                    promptTokens: u.promptTokens,
                    completionTokens: u.completionTokens || u.completion_tokens || 0,
                    totalTokens: u.totalTokens || u.total_tokens || u.promptTokens
                };
                measured = true;
            }
        } catch(e) {}
        if (!measured) {
            const p = estimateTokens(researchPrompt);
            const c = estimateTokens(researchBrief);
            rUsage = { promptTokens: p, completionTokens: c, totalTokens: p + c };
        }

        llmUsages.push({
            AgentName: 'Research Agent',
            ModelName: researchModel,
            Provider: measured ? 'OpenRouter' : 'OpenRouter (estimated, excludes ReAct scratchpad)',
            PromptTokens: rUsage.promptTokens,
            CompletionTokens: rUsage.completionTokens,
            TotalTokens: rUsage.totalTokens,
            TotalCostUsd: (rUsage.totalTokens / 1000) * getCost(researchModel)
        });
    } catch(e) {}

    // Dynamically reconstruct the prompt string to estimate length
    let basePrompt = `Analyze the following .NET project files, Repository File Tree, and Roslyn Upgrade Assistant output.
Your task is to produce a complete .NET migration plan.
CRITICAL: NEVER include 'Microsoft.NETCore.App' or 'Microsoft.AspNetCore.App' in package_updates or nuget_versions_needed. These are framework implicit references, NOT NuGet packages, and trying to add them via CLI will cause execution failure.
CRITICAL: If the code uses .WithOpenApi(), you MUST add Microsoft.AspNetCore.OpenApi to package_updates with action "add".
CRITICAL: For Deprecated WebClient or RNGCryptoServiceProvider, you MUST put the replacement logic inside file_changes. The new code MUST be valid C# (e.g., use await HttpClient.GetStringAsync and change the method signature to async Task<IActionResult>). Do not put code changes in startup_changes if they require actual file modifications.
IMPORTANT: Do NOT output multiple overlapping ReplaceFileContent actions for the same file. If you need to make multiple changes to a single file, you MUST combine them into a single ReplaceFileContent action that replaces a larger block of code containing all your changes.
IMPORTANT: When specifying file paths in your plan, you MUST refer to the "REPOSITORY FILE TREE" in the input below. Use the EXACT full relative path shown there. Do NOT guess or hallucinate paths.
CRITICAL: Do NOT hallucinate files that do not exist in the repository. Always use Program.cs for configuration in .NET 6+.
CRITICAL: Extract the Source Framework from the csproj or Roslyn output. It is usually net6.0, net7.0, or netcoreapp3.1.
IMPORTANT: Your response MUST be valid JSON.
Every required property defined in the schema MUST be present.
estimated_changes MUST be an integer.
risk_level MUST be one of: low, medium, high.
action MUST be one of: update, remove, add, no_update.

Use these inputs:
- Repository File Tree & Roslyn Analysis
- Known Patterns`;

    let customPrompt = '';
    try { customPrompt = $('Webhook').first().json.body.custom_prompt || ''; } catch(e) {}

    let repoProfile = '';
    try { repoProfile = $('Webhook').first().json.body.repository_profile || '[]'; } catch(e) {}

    let roslynOutput = '';
    try { roslynOutput = ($('Pre-Analyzer Agent Telemetry').first().json.stdout || '').substring(0,8000); } catch(e) {}

    let knownPatterns = '';
    try { knownPatterns = ($('Load Known Patterns').first().json.known_patterns || '').substring(0,2000); } catch(e) {}

    let fullPrompt = basePrompt + customPrompt + repoProfile + roslynOutput + knownPatterns;

    // The old fallback was a hardcoded 'qwen/qwen3-32b' and the $evaluateExpression
    // above it returns falsy here, so every job logged a model that is not on the
    // node. The literal below is written by patch_v68_part1.js from the export, so
    // it is right unless someone changes the model in the n8n UI without re-exporting.
    let analyzerModel = "openai/gpt-5-mini";
    try {
      const m = $evaluateExpression('{{ $node["Analyzer LLM"].parameter.model }}');
      if (m) analyzerModel = m;
    } catch(e) {}

    let agentOutput = $('Analyzer Agent').first().json || {};
    let usage = extractTokenUsage('Analyzer Agent', fullPrompt, agentOutput);
    let cost = (usage.totalTokens / 1000) * getCost(analyzerModel);

    llmUsages.push({
        AgentName: 'Analyzer Agent',
        ModelName: analyzerModel,
        Provider: (usage && usage.measured) ? 'OpenRouter' : 'OpenRouter (estimated)',
        PromptTokens: usage.promptTokens,
        CompletionTokens: usage.completionTokens,
        TotalTokens: usage.totalTokens,
        TotalCostUsd: cost
    });
} catch(e) {}

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:5153/api/migrationjob/' + jobId + '/metrics',
    body: {
      ExecutionTimeMs: executionTimeMs,
      Phase1ExecutionTimeMs: executionTimeMs,
      InitialErrorCount: iterations > 0 ? 15 : 0,
      ResidualErrorCount: 0,
      ErrorFixerIterations: iterations,
      SuccessRate: 100.0,
      RegressionRate: 0.0,
      NodeExecutions: nodeExecutions,
      Phase1Success: true,
      LlmUsages: llmUsages
    },
    json: true
  });
} catch (e) {}
return $input.all();

// microsoft_docs_search over the MCP HTTP endpoint. The endpoint is stateless
// (no initialize handshake, no session id) and SSE-framed, so parse "data: ".
//
// A raw search is ~20-24k chars / 10 results. Every result lands in the ReAct
// scratchpad and is re-sent on every later turn, so cap the bodies and keep the
// metadata: contentUrl is the only part the brief actually cites.
const q = String(query.query || '').trim();
if (!q) return 'ERROR: query is required.';

const CAP = 700;

// Only drop desktop-stack hits when this repo is not itself a desktop project.
let isDesktop = false;
try {
  const dump = $('Run Roslyn Upgrade Assistant').first().json.stdout || '';
  isDesktop = /<UseWPF>|<UseWindowsForms>|Microsoft\.NET\.Sdk\.WindowsDesktop/i.test(dump);
} catch (e) {}
const DESKTOP = /\/desktop\/winforms|\/wpf|\/xamarin|\/maui|winforms-applications|wpf-applications/i;

// A toolCode node that catches its own errors can never trigger n8n's
// retryOnFail, so the v6.4 retry policy this node used to carry as an
// mcpClientTool has to be re-implemented here. 'fetch failed' is undici's
// "connection never got off the ground" and is exactly the blip worth retrying.
const helpers = this.helpers;
async function callMcp(toolName, args) {
  let lastErr;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      return await helpers.httpRequest({
        method: 'POST',
        url: 'https://learn.microsoft.com/api/mcp',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
        body: { jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name: toolName, arguments: args } },
        json: false
      });
    } catch (e) {
      lastErr = e;
      if (attempt < 3) await new Promise(function (r) { setTimeout(r, 2000 * attempt); });
    }
  }
  throw lastErr;
}

try {
  const res = await callMcp('microsoft_docs_search', { query: q });
  const line = String(res).split('\n').find(function (l) { return l.indexOf('data: ') === 0; });
  if (!line) return 'MS Learn returned no parsable payload for "' + q + '".';
  const all = JSON.parse(JSON.parse(line.slice(6)).result.content[0].text).results || [];
  if (!all.length) return 'No Microsoft Learn results for "' + q + '".';

  const kept = isDesktop ? all : all.filter(function (r) { return !DESKTOP.test(r.contentUrl || ''); });
  const use = kept.length ? kept : all;
  const dropped = all.length - use.length;

  let out = use.map(function (r) {
    return r.title + '\n' + r.contentUrl + '\n' + String(r.content || '').slice(0, CAP);
  }).join('\n---\n');
  if (dropped) {
    out += '\n---\n(' + dropped + ' desktop-stack result(s) omitted: this is not a WinForms/WPF project)';
  }
  out += '\n\n(Excerpts are capped at ' + CAP + ' chars. If you need a type full member list to verify a replacement, call fetch_ms_learn_page on its contentUrl. Do that sparingly: it is the most expensive call available.)';
  return out;
} catch (e) {
  return 'MS Learn search failed for "' + q + '": ' + e.message;
}

// Resolve the newest version of a NuGet package that is COMPATIBLE with a target framework.
// Uses the NuGet V3 registration hive (dependencyGroups[].targetFramework) + vulnerability data.
const pkg = String(query.packageId || '').trim();
const tfm = String(query.targetFramework || 'net8.0').trim().toLowerCase();

if (!pkg) return 'ERROR: packageId is required.';

const FRAMEWORK_REFS = ['microsoft.netcore.app', 'microsoft.aspnetcore.app', 'microsoft.windowsdesktop.app'];
if (FRAMEWORK_REFS.includes(pkg.toLowerCase())) {
  return `ERROR: ${pkg} is an implicit framework reference, not a NuGet package. Do not add it.`;
}

// Ordered compatibility fallback: a package group is usable if it is this TFM or anything below it.
const LADDER = {
  'net10.0': ['net10.0','net9.0','net8.0','net7.0','net6.0','net5.0','netcoreapp3.1','netstandard2.1','netstandard2.0'],
  'net9.0':  ['net9.0','net8.0','net7.0','net6.0','net5.0','netcoreapp3.1','netstandard2.1','netstandard2.0'],
  'net8.0':  ['net8.0','net7.0','net6.0','net5.0','netcoreapp3.1','netstandard2.1','netstandard2.0'],
  'net7.0':  ['net7.0','net6.0','net5.0','netcoreapp3.1','netstandard2.1','netstandard2.0'],
  'net6.0':  ['net6.0','net5.0','netcoreapp3.1','netstandard2.1','netstandard2.0']
};
const allowed = LADDER[tfm] || LADDER['net8.0'];

function normTfm(s) {
  if (!s) return 'any';
  let t = String(s).toLowerCase().trim();
  if (t.startsWith('.netcoreapp,version=v')) t = 'net' + t.split('v')[1];
  else if (t.startsWith('.netstandard,version=v')) t = 'netstandard' + t.split('v')[1];
  else if (t.startsWith('.netframework,version=v')) t = 'netframework' + t.split('v')[1];
  return t.split('-')[0]; // drop platform suffix (net8.0-windows -> net8.0)
}

try {
  const reg = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.nuget.org/v3/registration5-gz-semver2/${pkg.toLowerCase()}/index.json`,
    json: true
  });

  // Flatten pages (inlined items, or fetch the page if not inlined)
  // Fetch all non-inlined registration pages in parallel instead of one at a time.
  const pages = await Promise.all((reg.items || []).map(async (page) => {
    if (page.items) return page.items;
    try {
      const p = await this.helpers.httpRequest({ method: 'GET', url: page['@id'], json: true });
      return p.items || [];
    } catch (e) { return []; }
  }));
  let entries = [];
  for (const items of pages) {
    for (const it of items) if (it.catalogEntry) entries.push(it.catalogEntry);
  }

  entries = entries.filter(e => e.listed !== false && !String(e.version).includes('-'));
  entries.sort((a, b) => {
    const pa = String(a.version).split('.').map(Number);
    const pb = String(b.version).split('.').map(Number);
    for (let i = 0; i < 4; i++) { if ((pa[i]||0) !== (pb[i]||0)) return (pb[i]||0) - (pa[i]||0); }
    return 0;
  });

  if (!entries.length) return `No listed stable versions found for ${pkg}.`;

  // v6.9: same policy as the 'NuGet Version Lookup' node, so the version the
  // agent researches is the version the plan ships. Before this they disagreed:
  // the tool returned newest-compatible while the node re-pinned to the lowest
  // compatible major, and job 98's risk_notes talked about AutoMapper 16.2.0
  // while package_updates shipped 15.1.3.
  const isCompatible = (e) => {
    const groups = (e.dependencyGroups || []).map(g => normTfm(g.targetFramework));
    if (!groups.length || groups.includes('any')) return true;
    return groups.some(g => allowed.includes(g));
  };
  const majorOf = (v) => Number(String(v || '0').split('-')[0].split('.')[0]) || 0;
  const cmpAscV = (a, b) => {
    const pa = String(a).split('-')[0].split('.').map(Number);
    const pb = String(b).split('-')[0].split('.').map(Number);
    for (let i = 0; i < 4; i++) { if ((pa[i]||0) !== (pb[i]||0)) return (pa[i]||0) - (pb[i]||0); }
    return 0;
  };
  const licOf = (e) => String((e && e.licenseExpression) || '').trim();

  const compatible = entries.filter(isCompatible);   // entries is newest-first
  const newestCompatible = compatible.length ? compatible[0] : null;

  let chosen = null;
  let reason = '';
  if (compatible.length) {
    const cur = String(query.currentVersion || '').trim();
    const forward = cur ? compatible.filter(e => cmpAscV(e.version, cur) >= 0) : compatible.slice();
    const pool0 = forward.length ? forward : compatible.slice();
    const clean = pool0.filter(e => !(e.vulnerabilities || []).length && !e.deprecation);
    let pool = clean.length ? clean : pool0;
    const fromEntry = cur ? entries.find(e => String(e.version) === cur) : null;
    const fromLic = fromEntry ? licOf(fromEntry) : '';
    if (fromLic) {
      const sameLic = pool.filter(e => licOf(e) === fromLic);
      if (sameLic.length) pool = sameLic;
    }
    pool.sort((a, b) => cmpAscV(a.version, b.version));
    const lowestMajor = majorOf(pool[0].version);
    const inMajor = pool.filter(e => majorOf(e.version) === lowestMajor);
    inMajor.sort((a, b) => cmpAscV(b.version, a.version));
    chosen = inMajor[0];
    reason = `lowest ${tfm}-compatible major with no advisory (highest patch in it); minimises unverifiable API change`;
  }

  if (!chosen) {
    const newest = entries[0];
    return `WARNING: no version of ${pkg} declares a dependency group compatible with ${tfm}. ` +
           `Newest stable is ${newest.version} (groups: ${(newest.dependencyGroups||[]).map(g=>normTfm(g.targetFramework)).join(', ')||'none'}). ` +
           `Do NOT pin this blindly; flag for human review.`;
  }

  const vulns = (chosen.vulnerabilities || []).map(v => `severity=${v.severity} ${v.advisoryUrl}`);
  const deps = (chosen.dependencyGroups || [])
    .filter(g => allowed.includes(normTfm(g.targetFramework)))
    .flatMap(g => (g.dependencies || []).map(dep => `${dep.id} ${dep.range}`));

  // Is it worth updating at all?
  const current = String(query.currentVersion || '').trim();

  return JSON.stringify({
    package: chosen.id || pkg,
    current_version: current || null,
    resolved_version: chosen.version,
    target_framework: tfm,
    compatible: true,
    why: reason,
    deprecated: chosen.deprecation ? (chosen.deprecation.message || 'deprecated') : null,
    vulnerabilities: vulns.length ? vulns : null,
    transitive_dependencies: deps.slice(0, 15),
    newest_stable_overall: entries[0].version,
    newest_compatible: newestCompatible ? newestCompatible.version : null,
    licence: licOf(chosen) || '(non-SPDX, see nuget.org)',
    note: (newestCompatible && newestCompatible.version !== chosen.version)
      ? `A newer compatible version exists (${newestCompatible.version}) but ${chosen.version} is the smallest safe jump. Plan against ${chosen.version} - that is what the pipeline will pin.`
      : (entries[0].version !== chosen.version
          ? `Newest overall (${entries[0].version}) is NOT compatible with ${tfm}; use ${chosen.version}.`
          : null)
  }, null, 2);

} catch (e) {
  return `Lookup failed for ${pkg}: ${e.message}. Do not guess a version - mark it for human review.`;
}

