let jobId = 'unknown';
try { jobId = $('Webhook').first()?.json?.body?.job_id; } catch(e) {}

let brief = '';
try { brief = $('Research Agent').first()?.json?.output || ''; } catch(e) {}

// Hard backstop: strip markdown code fences regardless of what the agent produced.
// Nested ``` blocks inside the brief have been observed to make the downstream
// JSON-formatter model loop until it hits its token ceiling.
brief = brief.replace(/```[a-zA-Z]*\n?/g, '').replace(/```/g, '');

// ── Stall guard ─────────────────────────────────────────────────────────────
// When the agent exhausts its iterations LangChain returns this sentinel as the
// whole output. Left alone it flows downstream as a "brief": no file paths are
// extracted, no verbatim source is attached, and the formatter dutifully emits
// an empty plan that the dashboard then presents as ready to approve. Fail the
// run instead - the backend marks the job Failed when the webhook errors.
if (/^\s*Agent stopped due to max iterations\.?\s*$/i.test(brief)) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'http://host.docker.internal:5153/api/migrationjob/' + jobId + '/logs',
      body: {
        level: 'error',
        phase: 'Analyze',
        message: 'Research Agent hit its tool-call limit before producing a brief. No plan can be built from this run - re-run the analysis.',
        details: brief
      },
      json: true
    });
  } catch (e) {}
  throw new Error('Research Agent stopped on maxIterations without producing a brief');
}

// ── Verbatim source attachment ──────────────────────────────────────────────
// The formatter has no tools, so it can only emit a byte-exact `old` snippet for a
// file whose real contents are somewhere in its context. The Roslyn dump only cats
// the csproj files, Program/Startup and the first 3 controllers - so findings in
// Utils/ or Services/ used to hit the "cannot see the surrounding lines -> risk_notes"
// rule and never became file_changes. Pull the real bytes for every file the brief names.
const MAX_FILES = 15;
const MAX_FILE_CHARS = 20000;
const MAX_TOTAL_CHARS = 60000;

const jid = Number(jobId);
const candidates = [];
const pathRe = /[A-Za-z0-9_][A-Za-z0-9_.\/-]*\.(?:cs|csproj|cshtml|props|targets|config)\b/g;
let m;
while ((m = pathRe.exec(brief)) !== null) {
  const p = m[0].replace(/^\.\//, '');
  if (p.indexOf('://') !== -1) continue;          // URL, not a repo path
  if (/(^|\/)(bin|obj)\//.test(p)) continue;       // build output
  if (candidates.indexOf(p) === -1) candidates.push(p);
}

// Keep only paths that actually exist in the repository. The extractor pulls any
// filename-shaped token out of the brief, including ones cited to say they are ABSENT
// ("no \`Startup.cs\`"), which then showed up in the log as a failed read.
let treeFiles = [];
try {
  const tree = ($('Run Roslyn Upgrade Assistant').first().json.stdout || '')
    .split('=== CSPROJ FILES ===')[0];
  treeFiles = tree.split('\n').map(l => l.trim()).filter(l => l && l.indexOf(' ') === -1);
} catch (e) {}
if (treeFiles.length) {
  for (let i = candidates.length - 1; i >= 0; i--) {
    const p = candidates[i];
    const known = treeFiles.some(t => t === p || t.endsWith('/' + p));
    if (!known) candidates.splice(i, 1);
  }
}

// The brief often cites a file twice - once with its full path and once by bare name
// ("LegacyService.cs line 3"). Both resolve to the same file, so drop the bare form.
const paths = candidates.filter(function (p) {
  if (p.indexOf('/') !== -1) return true;
  return !candidates.some(function (o) { return o !== p && o.endsWith('/' + p); });
});

const attachments = [];
const missing = [];
let total = 0;

if (Number.isFinite(jid)) {
  for (const p of paths.slice(0, MAX_FILES)) {
    if (total >= MAX_TOTAL_CHARS) break;
    try {
      // No startLine/maxLines: the unpaginated response returns the exact file bytes.
      // The paginated one prefixes every line with "N| ", which would poison old snippets.
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: 'http://host.docker.internal:5153/api/files/read',
        body: { jobId: jid, filePath: p },
        json: true
      });
      let content = (res && (res.content || res.Content)) || '';
      if (!content) { missing.push(p); continue; }
      content = content.replace(/```/g, '');
      if (content.length > MAX_FILE_CHARS) { missing.push(p + ' (too large to inline)'); continue; }
      attachments.push('--- ' + p + ' ---\n' + content);
      total += content.length;
    } catch (e) {
      missing.push(p);
    }
  }
}

if (attachments.length) {
  brief += '\n\n=== VERBATIM SOURCE (authoritative - the exact bytes on disk) ===\n' +
           'Each file below is reproduced IN FULL. For these files you CAN see every surrounding\n' +
           'line and every call site, so emit real file_changes for them - do NOT route them to\n' +
           'risk_notes for lack of context. Copy each `old` snippet byte for byte out of this\n' +
           'section, preserving indentation exactly.\n\n' +
           attachments.join('\n\n');
}

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:5153/api/migrationjob/' + jobId + '/logs',
    body: {
      level: 'info',
      phase: 'Analyze',
      message: 'Research Agent brief produced (docs + NuGet grounded). Verbatim source attached for ' +
               attachments.length + ' file(s)' + (missing.length ? '; unavailable: ' + missing.join(', ') : '') + '.',
      details: brief
    },
    json: true
  });
} catch (e) {}

// research_end splits the two agents' spans for Post Quantitative Metrics.
// Without it the formatter was charged the Research Agent's time too: job 97
// recorded 882s against 'Analyzer Agent' when the formatter actually took 106s.
return [{ json: { research_brief: brief, research_end: Date.now() } }];

// microsoft_docs_fetch. An API reference page is ~91k chars (4x a search) and
// the member tables sit near the END of it - on XmlReader, line ~792 of ~960.
// Head truncation would cut exactly what this tool exists to provide, so slice
// the member sections instead: 100% of the member surface, ~59% smaller.
const url = String(query.url || '').trim();
if (!/^https:\/\/learn\.microsoft\.com\//.test(url)) {
  return 'ERROR: url must be a https://learn.microsoft.com/... URL (use a contentUrl from microsoft_docs_search).';
}
const HARD_CAP = 40000;

// See the note in microsoft_docs_search: a toolCode that catches its own errors
// never reaches n8n's retryOnFail, so the retry lives here.
const helpers = this.helpers;
async function callMcp(toolName, args) {
  let lastErr;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      return await helpers.httpRequest({
        method: 'POST',
        url: 'https://learn.microsoft.com/api/mcp',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' },
        body: { jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name: toolName, arguments: args } },
        json: false
      });
    } catch (e) {
      lastErr = e;
      if (attempt < 3) await new Promise(function (r) { setTimeout(r, 2000 * attempt); });
    }
  }
  throw lastErr;
}

try {
  const res = await callMcp('microsoft_docs_fetch', { url: url });
  const line = String(res).split('\n').find(function (l) { return l.indexOf('data: ') === 0; });
  if (!line) return 'MS Learn returned no parsable payload for ' + url;
  let md = JSON.parse(line.slice(6)).result.content[0].text || '';
  const before = md.length;

  const lines = md.split('\n');
  const start = lines.findIndex(function (l) { return /^## (Constructors|Fields|Properties|Methods)\b/.test(l); });
  if (start > -1) {
    let end = lines.findIndex(function (l, i) { return i > start && /^## (Applies to|See also)\b/.test(l); });
    if (end <= start) end = lines.length;
    // Keep the Definition header (type signature, namespace, assembly) plus the members.
    const head = lines.slice(0, Math.min(start, 40)).join('\n');
    md = head + '\n' + lines.slice(start, end).join('\n');
  }
  if (md.length > HARD_CAP) md = md.slice(0, HARD_CAP) + '\n...[truncated at ' + HARD_CAP + ' chars]';
  return '--- ' + url + ' (' + before + ' -> ' + md.length + ' chars) ---\n' + md;
} catch (e) {
  return 'MS Learn fetch failed for ' + url + ': ' + e.message;
}

